// Generates docs/n5-review-sheet.md: every original sentence, passage and question, with checkboxes, for a proficient
// Japanese speaker to review. Run:  node tools/n5-review-sheet.mjs   (regenerate after editing src/n5)
import fs from "node:fs";
import path from "node:path";
import { root, loadContent, plain, kana } from "./n5-lib.mjs";

const c = loadContent();
const vocab = new Map(c.vocab.map((v) => [v.id, v]));
const L = [];
L.push("# N5 content review sheet", "",
  "Generated by `node tools/n5-review-sheet.mjs`. **Everything below is original text written for this app and has NOT yet been",
  "reviewed by a proficient Japanese speaker.** Spelling and readings are machine-checked against KANJIDIC2/JMdict",
  "(`src/n5/verification.json`); *naturalness, level and answer uniqueness are not.*", "",
  "For each item please check: **N** natural Japanese · **L** suitable for a beginner (JLPT N5 level) · **R** readings correct ·",
  "**A** (questions) exactly one defensible answer. Tick the box when reviewed; note problems beside the item.", "");
const row = (id, ja, en) => `- [ ] \`${id}\` ${plain(ja)}  \n  ${kana(ja)} — ${en}`;
for (const d of c.days) {
  const u = c.meta.units.find((x) => x.id === d.unit);
  L.push(`## Unit ${u.id}: ${u.title} (${u.kanji.join(" ")})`, "", "### Sentences", "");
  for (const s of d.sentences) L.push(row(s.id, s.ja, s.en));
  L.push("", `### Passage — ${plain(d.passage.title)} (${d.passage.titleEn})`, "");
  d.passage.paragraphs.forEach((p, i) => L.push(row(`${d.passage.id}.${i + 1}`, p, d.passage.paragraphsEn[i])));
  L.push("", "### Passage questions", "");
  for (const q of d.passage.questions) {
    L.push(`- [ ] \`${q.id}\` ${plain(q.q)} — *${q.qEn}*`);
    q.options.forEach((o, i) => L.push(`  - ${i === q.answer ? "**✔**" : "✘"} ${plain(o)}`));
    L.push(`  - why: ${q.explain}`);
  }
  L.push("", "### Fill-in-the-blank items", "");
  for (const q of d.cloze) {
    const s = d.sentences.find((x) => x.id === q.sentence), v = vocab.get(q.blank);
    L.push(`- [ ] \`${q.id}\` ${plain(s.ja).replace(plain(v.ruby), "＿＿")} — answer **${plain(v.ruby)}**; wrong: ${q.options.map((o) => plain(vocab.get(o).ruby)).join("、")}  \n  ${q.explain}`);
  }
  L.push("");
}
L.push("## Look-alike spellings (orthography questions)", "", "Each wrong spelling should look like the right one but must not be a normal word with the same reading (checked by machine).", "");
for (const v of c.vocab) L.push(`- [ ] ${plain(v.ruby)} → ${v.lookalikes.join("、")}`);
fs.mkdirSync(path.join(root, "docs"), { recursive: true });
fs.writeFileSync(path.join(root, "docs", "n5-review-sheet.md"), L.join("\n") + "\n");
console.log(`Wrote docs/n5-review-sheet.md (${L.length} lines)`);
